import * as S from './state.mjs';
import {ensureCalendar,addDays,dayNumber,monthDays,eventsOn,validateTargetDate} from './calendar-core.mjs';
import {beginCalendarHoliday,nextCalendarAction,prepareCalendarGame,advanceCalendarDay} from './calendar-operations.mjs';
import {officeCounts,syncOffice,ensureOffice,decisionOptions} from './newsroom.mjs';
import {assertCanAdvance} from './compliance.mjs';
import {icon,crumbLabel} from './presentation.mjs';
const arg=v=>esc(JSON.stringify(v));
const label=(date,opts={})=>new Date(dayNumber(date)*86400000).toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric',...opts});
export function installCalendarUI({views,initialize,isBusy,setBusy,settleRound}){
 let month=ensureCalendar(state).date.slice(0,7),selected=ensureCalendar(state).date,target=addDays(ensureCalendar(state).date,7),stopping=false;
 const previous=ensureCalendar(state).session;if(previous?.status==='running'){previous.status='paused';previous.message='The holiday is ready to resume.';}
 function mutate(fn){state=S.transact(state,fn);save();}
 const phaseName=()=>state.phase==='offseason'?'Offseason':state.phase==='playoffs'?'Postseason':'Regular season';
 // Holiday banners: a running simulation shows a block progress bar; a paused one says why, links
 // to the screen that fixes it and lists the waiting decisions so they can be answered in place.
 function banner(c,session,busy){
  if(session?.status==='running'){const from=session.started||c.date,total=Math.max(1,dayNumber(session.target)-dayNumber(from)),done=Math.max(0,dayNumber(c.date)-dayNumber(from)),share=Math.min(1,done/total),filled=Math.round(share*20);
   return `<div class="calendar-progress" role="status"><span class="calendar-banner-icon" aria-hidden="true">▶▶</span><span class="calendar-banner-copy"><b>Simulating to ${label(session.target,{year:'numeric'})}</b><small>${label(c.date,{weekday:'short'})} · ${session.rounds} round${session.rounds===1?'':'s'} completed</small><span class="calendar-blocks" role="img" aria-label="${Math.round(share*100)}% of the way">${Array.from({length:20},(_,i)=>`<i class="${i<filled?'on':''}"></i>`).join('')}</span></span><span class="calendar-banner-actions"><button class="secondary small" onclick="Calendar.stop()">${stopping?'Stopping…':'Stop simulation'}</button></span></div>`;}
  if(session?.status!=='paused')return '';
  const inbox=/inbox/i.test(session.message||''),fix=inbox?`<button class="secondary small" onclick="W.open('Inbox')">Open inbox</button>`:/Begin next season/.test(session.message||'')?`<button class="secondary small" onclick="W.open('Draft')">Open Draft room</button>`:session.route?`<button class="secondary small" onclick="W.open('${esc(session.route)}')">Fix in ${esc(crumbLabel(session.route))}</button>`:'';
  return `<div class="calendar-paused" role="status"><span class="calendar-banner-icon" aria-hidden="true">❚❚</span><span class="calendar-banner-copy"><b>Holiday paused</b><small>${esc(session.message)}</small><em>Return date ${label(session.target,{weekday:'short',year:'numeric'})}</em></span><span class="calendar-banner-actions">${fix}<button class="small" onclick="Calendar.resume()" ${busy?'disabled':''}>Resume →</button></span></div>${inbox?waitingDecisions():''}`;
 }
 function dayCell(date,c){const e=eventsOn(state,date),game=e.find(e=>e.game),isToday=date===c.date;let body='';
  if(game){const g=game.game,home=g.a===state.team,o=home?g.b:g.a,k=home?0:1,res=g.score?(g.score[k]>g.score[1-k]?'W':g.score[k]<g.score[1-k]?'L':'T'):'';body=`<img src="${logoSource(o)}" alt="${esc(clubs[o][2])}"><em class="calendar-evchip game ${res?'res-'+res.toLowerCase():home?'home':''}">${res?`${res} ${g.score[k]}–${g.score[1-k]}`:`${home?'vs':'@'} ${esc(clubs[o][0])}`}</em>`;}
  else if(e.length)body=`<em class="calendar-evchip ${/bye/i.test(e[0].kind)?'bye':'league'}">${esc(e[0].kind)}</em>${e.length>1?`<small>+${e.length-1} more</small>`:''}`;
  return `<button class="calendar-day ${date.slice(0,7)!==month?'outside':''} ${isToday?'today':''} ${date===selected?'selected':''} ${e.length?'has-event':''} ${game?'has-game':''}" onclick="Calendar.pick('${date}')" aria-label="${label(date,{weekday:'long',year:'numeric'})}${e.length?', '+e.map(x=>x.kind).join(', '):''}" aria-pressed="${date===selected}"><span>${Number(date.slice(-2))}</span>${body}</button>`;}
 function eventCard(e){if(!e.game)return `<div class="calendar-event"><b>${esc(e.kind)}</b><small>${esc(e.status||'')}</small></div>`;const g=e.game,side=(t,k)=>`<span class="calendar-event-team ${t===state.team?'me':''}"><img src="${logoSource(t)}" alt="">${esc(clubs[t][2])}${g.score?`<strong>${g.score[k]}</strong>`:''}</span>`;return `<div class="calendar-event game"><b>${esc(e.kind)}</b>${side(g.a,0)}${side(g.b,1)}<small>${g.score?'Final':esc(e.status||'Scheduled')}</small></div>`;}
 function view(){const c=ensureCalendar(state),session=c.session,days=monthDays(month),events=eventsOn(state,selected),future=selected>c.date,busy=isBusy();
  return `<div class="calendar-workspace"><section class="calendar-hero"><div><span class="eyebrow">YOUR FOOTBALL YEAR</span><h2>${label(c.date,{weekday:'long',year:'numeric'})}</h2><p>${esc(clubs[state.team][1]+' '+clubs[state.team][2])} · ${phaseName()}</p></div><div class="calendar-deputy">${icon('calendar')}<span><small>NEXT MATCHDAY</small><b>${c.nextRoundDate&&state.phase!=='offseason'?label(c.nextRoundDate,{weekday:'short'}):'Offseason'}</b><small>The calendar stops whenever a decision needs you.</small></span></div></section>${banner(c,session,busy)}<div class="calendar-layout"><section class="calendar-month"><div class="calendar-month-head"><div><button class="secondary small" aria-label="Previous month" onclick="Calendar.month(-1)">◀</button><h3>${label(month+'-01',{month:'long',year:'numeric',day:undefined})}</h3><button class="secondary small" aria-label="Next month" onclick="Calendar.month(1)">▶</button></div><button class="secondary small" onclick="Calendar.today()">Today</button></div><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${days.map(date=>dayCell(date,c)).join('')}</div><div class="calendar-legend"><span><em class="calendar-evchip game">vs</em> Matchday</span><span><em class="calendar-evchip game res-w">W</em><em class="calendar-evchip game res-l">L</em> Result</span><span><em class="calendar-evchip league">Event</em> League date</span><span><i class="calendar-today-key"></i> Today</span><button class="link" onclick="W.open('Schedule')">Full fixture list →</button></div></section><div class="calendar-side"><section><span class="eyebrow">${label(selected,{weekday:'long'})}</span><h3>${label(selected,{month:'long',year:'numeric'})}</h3>${events.map(eventCard).join('')||'<p>Preparation, recovery and club correspondence.</p>'}${future?`<button class="small" onclick="Calendar.start('${selected}')" ${busy?'disabled':''}>Simulate to this date →</button>`:''}</section><section><span class="eyebrow">GO ON HOLIDAY</span><h3>Choose your return date.</h3><label class="calendar-date-label">Simulation target<input aria-label="Simulation target date" type="date" min="${addDays(c.date,1)}" max="${addDays(c.date,730)}" value="${target}" onchange="Calendar.target(this.value)" ${busy?'disabled':''}></label><p>The calendar pauses for inbox decisions, interviews and roster problems so you can handle them yourself.</p><button onclick="Calendar.start()" ${busy?'disabled':''}>Simulate to date →</button><div class="calendar-shortcuts"><button class="secondary small" onclick="Calendar.start('${addDays(c.date,1)}')" ${busy?'disabled':''}>1 day</button><button class="secondary small" onclick="Calendar.start('${addDays(c.date,7)}')" ${busy?'disabled':''}>1 week</button><button class="secondary small" onclick="Calendar.start('${addDays(c.date,28)}')" ${busy?'disabled':''}>4 weeks</button></div></section></div></div></div>`;}
 function logoSource(team){const html=logo(team),match=html.match(/src=["']([^"']+)/);return match?.[1]||'';}
 async function start(date=target){if(isBusy()||animating){toast('Finish the current play before starting a holiday.');return;}try{initialize();mutate(s=>beginCalendarHoliday(s,date));}catch(e){toast(e.message);return;}pauseAuto();window.broadcast?.stop();setBusy(true);stopping=false;W.open('Calendar');render();let completed=false;
 try{for(let safety=0;safety<1000&&!stopping;safety++){const action=nextCalendarAction(state,date),session=ensureCalendar(state).session;if(action.kind==='done'){completed=true;break;}syncOffice(state);if(officeCounts(state).urgent||state.interviewPending||state.franchise.cinema?.active)throw Error('An urgent club matter or interview is waiting in your inbox.');
 const before=structuredClone(state);try{if(action.kind==='game'){mutate(s=>prepareCalendarGame(s,action.date));assertCanAdvance(state,{game:true});await settleRound({live:state.live});mutate(s=>{ensureCalendar(s).session.rounds++;});}else mutate(s=>advanceCalendarDay(s,action.date));}catch(e){state=before;throw e;}
 if(safety%7===0||action.kind==='game'){render();await new Promise(resolve=>setTimeout(resolve,0));}}
 mutate(s=>{const c=ensureCalendar(s);c.session.status=completed?'complete':'paused';c.session.message=completed?'Your selected return date has arrived.':'Stopped at your request.';});
 }catch(e){mutate(s=>{const c=ensureCalendar(s);c.session.status='paused';c.session.message=e.message;c.session.route=e.route||null;});toast(e.message);}finally{setBusy(false);month=ensureCalendar(state).date.slice(0,7);selected=ensureCalendar(state).date;target=addDays(selected,7);save();render();}}
 // Decisions that paused the holiday, answerable in place: answering resumes the simulation.
 function waitingDecisions(){const urgent=ensureOffice(state).messages.filter(m=>m.status==='pending'&&m.priority==='urgent').slice(0,3);const press=state.interviewPending?`<article class="calendar-decision"><div><span class="eyebrow">PRESS CONFERENCE</span><b>The media are waiting for you.</b></div><div class="calendar-decision-choices"><button class="small" onclick="advance()">Hold press conference</button></div></article>`:'';if(!urgent.length&&!press)return '';return `<section class="calendar-decisions" aria-label="Decisions waiting">${press}${urgent.map(m=>`<article class="calendar-decision"><div><span class="eyebrow">${esc(m.source||m.category||'DECISION')}</span><b>${esc(m.title)}</b>${m.summary?`<small>${esc(m.summary)}</small>`:''}</div><div class="calendar-decision-choices">${decisionOptions(m).map(c=>`<button class="secondary small" title="${esc(c.note||'')}" onclick="Office.respond('${m.id}','${c.id}');Calendar.resume()" ${isBusy()?'disabled':''}>${esc(c.text)}</button>`).join('')}</div></article>`).join('')}<p class="subtitle">Answering a decision resumes the simulation. <button class="link" onclick="W.open('Inbox')">Read it in full in the inbox</button></p></section>`;}
 window.Calendar={start,stop(){stopping=true;render();},resume(){const s=ensureCalendar(state).session;if(s)start(s.target);},target(v){target=v;},pick(v){selected=v;render();},today(){selected=ensureCalendar(state).date;month=selected.slice(0,7);render();},month(delta){const d=new Date(month+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);month=d.toISOString().slice(0,7);render();}};
 views.Calendar=view;
 F.holiday=(rounds=1)=>{const c=ensureCalendar(state),days=Math.min(700,Math.max(0,Number(rounds)-1)*7),returnDate=addDays(c.nextRoundDate||c.date,days);return start(returnDate);};F.stopHoliday=Calendar.stop;
}
